<?php
declare(strict_types=1);
$env=__DIR__.'/.env';$installed=is_file($env);if($installed){require __DIR__.'/v10-lib.php';$u=current_user();if(!$u){header('Location:login.php?next=repair.php');exit;}if(!in_array($u['role'],['super_admin','company_admin'],true)){http_response_code(403);exit('Forbidden');}}else{$ip=(string)($_SERVER['REMOTE_ADDR']??'');if(!in_array($ip,['127.0.0.1','::1'],true)){http_response_code(403);exit('Repair before install is only allowed from localhost.');}}
$msg='';$err='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if($installed)verify_csrf();try{$host=trim((string)$_POST['db_host']);$port=(int)$_POST['db_port'];$db=trim((string)$_POST['db_name']);$user=trim((string)$_POST['db_user']);$pass=(string)$_POST['db_pass'];if(!preg_match('/^[A-Za-z0-9_]+$/',$db))throw new RuntimeException('Invalid database name');$pdo=new PDO("mysql:host=$host;port=$port;dbname=$db;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$required=['companies','users'];$tables=$pdo->query('SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE()')->fetchAll(PDO::FETCH_COLUMN);if(count(array_intersect($required,$tables))!==count($required))throw new RuntimeException('CRM tables are missing. Run install.php or restore a backup.');$old=[];if(is_file($env)){foreach(file($env,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){if(str_contains($line,'=')){[$k,$v]=explode('=',$line,2);$old[trim($k)]=trim(trim($v),"\"'");}}}$old['DB_HOST']=$host;$old['DB_PORT']=(string)$port;$old['DB_DATABASE']=$db;$old['DB_USERNAME']=$user;$old['DB_PASSWORD']=$pass;$old['APP_KEY']=$old['APP_KEY']??bin2hex(random_bytes(32));$old['CRON_KEY']=$old['CRON_KEY']??bin2hex(random_bytes(24));$old['REPAIR_KEY']=$old['REPAIR_KEY']??bin2hex(random_bytes(24));$lines=[];foreach($old as $k=>$v)$lines[]=$k.'='.$v;file_put_contents($env,implode(PHP_EOL,$lines).PHP_EOL,LOCK_EX);$msg='Connection and .env repaired.';}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><title>Repair</title></head><body style="font-family:Arial;max-width:700px;margin:40px auto"><h1>CRM Repair</h1><?php if($msg):?><p><?=$msg?></p><?php endif;?><?php if($err):?><pre><?=htmlspecialchars($err,ENT_QUOTES,'UTF-8')?></pre><?php endif;?><form method="post"><?php if($installed):?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php endif;?><input name="db_host" value="127.0.0.1" placeholder="Host"><input name="db_port" value="3306" placeholder="Port"><input name="db_name" placeholder="Database"><input name="db_user" value="root" placeholder="User"><input name="db_pass" type="password" placeholder="Password"><button>Test and repair</button></form></body></html>
